# 1) replace inline figure links with "(Fig. N)" callouts
def repl(m):
    n = int(m.group(1))
    return f"(Fig. {n})"
text = re.sub(r"\[Fig (\d+)\]\(\.\./figures/[^)]+\)", repl, text)

# 2) build the grouped Figures section
fig_lines = ["", "## Figures", ""]
for n in sorted(figfile):
    p = os.path.join(FIGDIR, figfile[n])
    if not os.path.exists(p):
        continue
    cap = "Graphical abstract" if n == 0 else f"Figure {n}"
    fig_lines.append(f"![{cap}]({p.replace(os.sep, '/')})")
    fig_lines.append("")
    fig_lines.append(f"**{cap}.** {legend[n]}")
    fig_lines.append("")

text = text.rstrip() + "\n" + "\n".join(fig_lines) + "\n"

open(OUT, "w", encoding="utf-8").write(text)
print("wrote", OUT)
print("figures embedded:", sum(1 for n in figfile if os.path.exists(os.path.join(FIGDIR, figfile[n]))))
print("remaining raw figure links in body:", len(re.findall(r"\[Fig \d+\]\(", text.split("## Figures")[0])))
